cypress_script:
describe('Tool Tips functionality', () => {
  it('should display tooltip on hover over input field', () => {
    cy.visit('https://demoqa.com/tool-tips');
    cy.get('#toolTipTextField').trigger('mouseover');
    cy.get('.tooltip').should('be.visible');
  });

  it('should not change URL when hovering over elements', () => {
    cy.visit('https://demoqa.com/tool-tips');
    cy.url().should('eq', 'https://demoqa.com/tool-tips');
    cy.get('#toolTipTextField').trigger('mouseover');
    cy.get('#toolTipButton').trigger('mouseover');
    cy.url().should('eq', 'https://demoqa.com/tool-tips');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Tool Tips functionality', () => {
  test('should display tooltip on hover over input field', async ({ page }) => {
    await page.goto('https://demoqa.com/tool-tips');
    await page.hover('#toolTipTextField');
    const tooltip = await page.locator('.tooltip');
    await expect(tooltip).toBeVisible();
  });

  test('should not change URL when hovering over elements', async ({ page }) => {
    await page.goto('https://demoqa.com/tool-tips');
    const initialUrl = page.url();
    await page.hover('#toolTipTextField');
    await page.hover('#toolTipButton');
    await expect(page.url()).toBe(initialUrl);
  });
});
